INSERT INTO public.announcements (id, title, description, publisher_id, publisher_name, location_id, location_name, category, priority, action_url, verified, created_at, updated_at) VALUES ('ann-1', 'VITHack 2026 Registration Portal Is Now Live', 'Applications are officially open for VIT Bhopal’s largest national hackathon with ₹3,00,000 in prizes and direct venture incubation fast-tracks. Team sizes 2 to 4 members.', 'pub-innovation-club', 'Innovation & Entrepreneurship Cell', 'loc-ab-2', 'AB-2', 'Hackathon', 'high', '/events/event-hackathon-orientation', TRUE, '2026-09-04T08:00:00Z', '2026-09-16T17:42:13.931Z') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, updated_at = NOW();
INSERT INTO public.announcements (id, title, description, publisher_id, publisher_name, location_id, location_name, category, priority, action_url, verified, created_at, updated_at) VALUES ('ann-2', 'AI Club Workshop Today: Venue Confirmed at Seminar Hall', 'Reminder: The Hands-on Generative AI & LLM Systems workshop begins sharp at 4:00 PM in Seminar Hall (AB-1 Ground Floor). Please arrive 10 minutes early with your laptops.', 'pub-ai-club', 'AI & ML Club', 'loc-ab-1', 'AB-1', 'Workshop', 'urgent', '/events/event-ai-workshop', TRUE, '2026-09-04T09:30:00Z', '2026-09-16T17:42:13.931Z') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, updated_at = NOW();
INSERT INTO public.announcements (id, title, description, publisher_id, publisher_name, location_id, location_name, category, priority, action_url, verified, created_at, updated_at) VALUES ('ann-3', 'AB-1 & AB-2 Extended Study Hall Hours for Midterms', 'The AB-1 and AB-2 reading and project study halls will remain open until 1:00 AM on weekdays starting Monday. Silent zone policies will be strictly maintained by floor marshals.', 'pub-innovation-club', 'Academic Directorate', 'loc-ab-1', 'AB-1', 'Campus Notice', 'medium', '/locations/loc-ab-1', TRUE, '2026-09-03T14:00:00Z', '2026-09-16T17:42:13.931Z') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, updated_at = NOW();
INSERT INTO public.announcements (id, title, description, publisher_id, publisher_name, location_id, location_name, category, priority, action_url, verified, created_at, updated_at) VALUES ('ann-4', 'Campus Transit Shuttle Revised Timetable', 'New EV shuttle frequency: runs every 8 minutes between AB-1, AB-2, Girls Hostels (GH-1, GH-2), and Boys Hostels (BH-1 to BH-8) during morning peak transit (7:45 AM – 9:30 AM).', 'pub-innovation-club', 'Campus Administration', 'loc-ab-1', 'AB-1', 'Transit', 'low', '/locations/loc-ab-1', TRUE, '2026-09-02T11:00:00Z', '2026-09-16T17:42:13.931Z') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, updated_at = NOW();
INSERT INTO public.announcements (id, title, description, publisher_id, publisher_name, location_id, location_name, category, priority, action_url, verified, created_at, updated_at) VALUES ('ann-5', 'Inter-College Cultural Fest "Advitya 2026" Audition Call', 'Performers interested in music, band performances, and theatrical acts can sign up at the MPH registration desk. Slots assigned on first-come basis.', 'pub-cultural-club', 'Cultural & Performing Arts Guild', 'loc-mph', 'MPH (Sports Complex)', 'Cultural', 'medium', '/events/event-cultural-auditions', FALSE, '2026-09-01T16:00:00Z', '2026-09-16T17:42:13.931Z') ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, description = EXCLUDED.description, updated_at = NOW();
